    static void check(boolean b, String message) { if (!b) throw new AssertionError(message); }
    static SSLContext matching(boolean serve, boolean trust) throws Exception {
        KeyStore keys=KeyStore.getInstance("PKCS12");
        keys.load(new ByteArrayInputStream(Base64.getDecoder().decode(KEY)), "changeit".toCharArray());
        KeyManager[] km=null; TrustManager[] tm=null;
        if (serve) { KeyManagerFactory f=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm()); f.init(keys,"changeit".toCharArray()); km=f.getKeyManagers(); }
        if (trust) { KeyStore ts=KeyStore.getInstance(KeyStore.getDefaultType()); ts.load(null,null); ts.setCertificateEntry("fixture",keys.getCertificate("fixture")); TrustManagerFactory f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm()); f.init(ts); tm=f.getTrustManagers(); }
        SSLContext c=SSLContext.getInstance("TLS"); c.init(km,tm,null); return c;
    }
    static String headers(InputStream in) throws IOException {
        ByteArrayOutputStream out=new ByteArrayOutputStream(); int b, state=0;
        while ((b=in.read())!=-1 && out.size()<16384) {
            out.write(b); state=(state==0 && b==13)?1:(state==1 && b==10)?2:(state==2 && b==13)?3:(state==3 && b==10)?4:0;
            if(state==4) return out.toString("US-ASCII");
        }
        throw new IOException("incomplete headers");
    }
    static final class Proxy implements AutoCloseable {
        final ServerSocket listener; final SSLContext server; final boolean fail, drip; volatile boolean use405;
        final List<String> connects=Collections.synchronizedList(new ArrayList<>()), requests=Collections.synchronizedList(new ArrayList<>());
        final List<Throwable> errors=Collections.synchronizedList(new ArrayList<>());
        final List<Socket> sockets=Collections.synchronizedList(new ArrayList<>());
        final CountDownLatch gotRequests=new CountDownLatch(3);
        final ExecutorService pool=Executors.newCachedThreadPool(r->{ Thread t=new Thread(r,"fixture-proxy"); t.setDaemon(true); return t; });
        Proxy(SSLContext server, boolean fail, boolean drip) throws IOException {
            this.server=server; this.fail=fail; this.drip=drip;
            listener=new ServerSocket(0,20,InetAddress.getByName("127.0.0.1"));
            pool.execute(()->{ while(!listener.isClosed()) try { Socket s=listener.accept(); sockets.add(s); pool.execute(()->handle(s)); } catch(IOException | RejectedExecutionException e) { if(!listener.isClosed()) errors.add(e); break; } });
        }
        void handle(Socket plain) {
            try (Socket s=plain) {
                s.setSoTimeout(12000); String connect=headers(s.getInputStream()); connects.add(connect);
                s.getOutputStream().write("HTTP/1.1 200 Connection Established\r\n\r\n".getBytes(StandardCharsets.US_ASCII)); s.getOutputStream().flush();
                try (SSLSocket tls=(SSLSocket)server.getSocketFactory().createSocket(s,"localhost",s.getPort(),true)) {
                    tls.setUseClientMode(false); tls.setSoTimeout(12000); tls.startHandshake();
                    String request=headers(tls.getInputStream()); requests.add(request); gotRequests.countDown();
                    if (drip) {
                        OutputStream out=tls.getOutputStream(); out.write("HTTP/1.1 200 OK\r\nX-Slow: ".getBytes(StandardCharsets.US_ASCII)); out.flush();
                        for(int i=0;i<40;i++) { Thread.sleep(500); out.write('x'); out.flush(); }
                    } else {
                        String line=request.substring(0,request.indexOf("\r\n"));
                        int status=line.contains("login?") || line.contains("GET / HTTP") ? 401 : line.contains("auth/state") || line.contains("model_catalog") ? 403 : 405;
                        if(line.contains("chat/completions")) status=use405 ? 405 : 302;
                        String response="HTTP/1.1 "+status+" fixture\r\nLocation: https://redirect.invalid/never\r\nContent-Length: 999999\r\n\r\n";
                        tls.getOutputStream().write(response.getBytes(StandardCharsets.US_ASCII)); tls.getOutputStream().flush();
                        // No body is ever sent: the probe must finish with headers alone.
                        while(tls.getInputStream().read()!=-1) { }
                    }
                }
            } catch(Exception e) { if(!fail && !drip && !listener.isClosed()) errors.add(e); }
        }
        NetworkPolicy.Snapshot snapshot() throws Exception { return NetworkPolicy.parse(new JSONObject().put("mode","http_proxy").put("host","127.0.0.1").put("port",listener.getLocalPort())); }
        public void close() throws Exception { listener.close(); synchronized(sockets) { for(Socket s:sockets) try { s.close(); } catch(IOException ignored) {} } pool.shutdownNow(); pool.awaitTermination(2,TimeUnit.SECONDS); }
    }
    static void rows(JSONObject result, String[] kinds) throws Exception {
        check(result.getBoolean("ok"),"probe failed: "+result);
        for(int i=0;i<3;i++) { JSONObject r=result.getJSONArray("results").getJSONObject(i); check(kinds[i].equals(r.getString("kind")),"row: "+r); check(r.getBoolean("reachable")==!kinds[i].equals("tls"),"reachability: "+r); }
    }
    static void success(String provider, AtomicInteger cookies, AtomicInteger auth) throws Exception {
        SSLContext.setDefault(matching(false,true));
        try(Proxy p=new Proxy(matching(true,false),false,false)) {
            long start=System.nanoTime(); JSONObject result=ProviderEndpointProbe.probe(provider,p.snapshot());
            check(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)<4000,"response body was awaited");
            rows(result,new String[]{"auth_required","restricted","redirect"});
            check("reachable".equals(result.getString("verdict")),"verdict");
            check(p.gotRequests.await(2,TimeUnit.SECONDS),"missing requests");
            String host=provider.equals("workbuddy")?"copilot.tencent.com":"xiaohuanxiong.com";
            Set<String> lines=new HashSet<>();
            synchronized(p.requests) { for(String req:p.requests) { String[] parts=req.split("\r\n"); lines.add(parts[0]); check(parts.length==3 && parts[1].equals("Host: "+host) && parts[2].equals("Connection: close"),"unexpected request headers: "+req); } }
            if(provider.equals("workbuddy")) check(lines.equals(new HashSet<>(Arrays.asList("GET /login?platform=CLI HTTP/1.1","OPTIONS /v2/plugin/auth/state?platform=CLI HTTP/1.1","OPTIONS /v2/chat/completions HTTP/1.1"))),"WB paths: "+lines);
            else check(lines.equals(new HashSet<>(Arrays.asList("GET / HTTP/1.1","GET /api/web/llm/v2/model_catalog HTTP/1.1","OPTIONS /api/web/llm/v2/chat/completions HTTP/1.1"))),"raccoon paths: "+lines);
            check(p.connects.size()==3 && p.requests.size()==3,"redirect followed or missing connection");
            for(String c:p.connects) check(c.equals("CONNECT "+host+":443 HTTP/1.1\r\nHost: "+host+":443\r\n\r\n"),"CONNECT headers: "+c);
            check(p.errors.isEmpty(),"server errors: "+p.errors);
            p.use405=true; rows(ProviderEndpointProbe.probe(provider,p.snapshot()),new String[]{"auth_required","restricted","unverified"});
            check(cookies.get()==0 && auth.get()==0,"global cookie/authenticator called");
        }
    }
    public static void main(String[] args) throws Exception {
        SSLContext previous=SSLContext.getDefault(); CookieHandler oldCookies=CookieHandler.getDefault(); Authenticator oldAuth=null;
        AtomicInteger cookies=new AtomicInteger(), auth=new AtomicInteger();
        CookieHandler.setDefault(new CookieHandler() { public Map<String,List<String>> get(URI u,Map<String,List<String>> h) { cookies.incrementAndGet(); return Collections.singletonMap("Cookie",Collections.singletonList("secret=cookie")); } public void put(URI u,Map<String,List<String>> h) { cookies.incrementAndGet(); } });
        Authenticator.setDefault(new Authenticator() { protected PasswordAuthentication getPasswordAuthentication() { auth.incrementAndGet(); return new PasswordAuthentication("secret", "secret".toCharArray()); } });
        try {
            success("workbuddy",cookies,auth); success("raccoon",cookies,auth);
            // The existing fixture is trusted but names proxy-fixture.invalid, never either target.
            SSLContext.setDefault(NetworkPolicyOfflineTest.context(true,false));
            try(Proxy p=new Proxy(NetworkPolicyOfflineTest.context(false,true),true,false)) { rows(ProviderEndpointProbe.probe("workbuddy",p.snapshot()),new String[]{"tls","tls","tls"}); check(p.requests.isEmpty(),"wrong-name HTTP request"); }
            SSLContext.setDefault(NetworkPolicyOfflineTest.context(true,false));
            try(Proxy p=new Proxy(matching(true,false),true,false)) { rows(ProviderEndpointProbe.probe("raccoon",p.snapshot()),new String[]{"tls","tls","tls"}); check(p.requests.isEmpty(),"untrusted HTTP request"); }
            SSLContext.setDefault(matching(false,true));
            try(Proxy p=new Proxy(matching(true,false),false,true)) {
                ExecutorService caller=Executors.newSingleThreadExecutor(); long start=System.nanoTime();
                try { Future<JSONObject> f=caller.submit(()->ProviderEndpointProbe.probe("workbuddy",p.snapshot()));
                    check(p.gotRequests.await(4,TimeUnit.SECONDS),"drip requests");
                    check(ProviderEndpointProbe.probe("workbuddy",p.snapshot()).optBoolean("busy"),"single flight");
                    JSONObject result=f.get(12,TimeUnit.SECONDS); long ms=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start);
                    check(ms<12000 && result.getBoolean("ok"),"budget: "+ms);
                    for(int i=0;i<3;i++) check("timeout".equals(result.getJSONArray("results").getJSONObject(i).getString("kind")),"drip timeout: "+result);
                } finally { caller.shutdownNow(); }
            }
            check(cookies.get()==0 && auth.get()==0,"global handlers called");
            System.out.println("ProviderEndpointProbeTlsHttpTest OK");
        } finally { SSLContext.setDefault(previous); CookieHandler.setDefault(oldCookies); Authenticator.setDefault(oldAuth); }
    }
